/**
 * Multiplayer Context - React context for multiplayer state and functionality
 */

import {
    createContext,
    useCallback,
    useContext,
    useEffect,
    useRef,
    useState,
    ReactNode,
} from 'react'
import { v4 as uuidv4 } from 'uuid'
import { Unsubscribe } from 'firebase/database'
import { initializeFirebase, isFirebaseConfigured } from './firebaseConfig'
import {
    changePlayerSlot,
    checkLobby,
    closeLobby,
    createLobby,
    generateLobbyId,
    getAvailableSlots,
    joinLobby,
    kickPlayer,
    leaveLobby,
    setPlayerReady as setPlayerReadyInLobby,
    subscribeLobby,
    updateLobbyStatus,
    updatePlayerConfig as updatePlayerConfigInLobby,
    LobbyData,
    LobbyInfo,
    LobbyPlayer,
    PlayerConfig,
} from './lobbyManager'
import {
    isActionAllowedForClient,
    removeClientAction,
    sendClientAction,
    subscribeClientActions,
    subscribeGameState,
    syncGameState,
    ClientAction,
    ActionData,
} from './syncManager'
import { GameConfig } from '../../types'

// =============================================================================
// TYPES
// =============================================================================

type ConnectionStatus = 'disconnected' | 'connecting' | 'connected'

export interface MultiplayerContextValue {
    // State
    isMultiplayer: boolean
    isHost: boolean
    lobbyId: string | null
    lobbyData: LobbyData | null
    playerId: string
    playerSlot: number | null
    playerName: string
    connectionStatus: ConnectionStatus
    error: string | null
    firebaseReady: boolean
    hostDisconnected: boolean
    wasKicked: boolean
    clientDisconnected: boolean

    // Computed
    connectedPlayers: LobbyPlayer[]

    // Actions
    hostGame: (hostName: string, gameConfig: GameConfig) => Promise<string | null>
    joinGame: (joinLobbyId: string, name: string, slot: number) => Promise<boolean>
    checkLobbyExists: (checkId: string) => Promise<LobbyInfo | null>
    getSlots: () => number[]
    changeSlot: (newSlot: number) => Promise<boolean>
    kickPlayerFromLobby: (playerIdToKick: string) => Promise<boolean>
    startMultiplayerGame: (loadLobbyId?: string, forceHost?: boolean) => Promise<void>
    syncState: (state: unknown) => Promise<void>
    sendAction: (action: ClientAction) => Promise<void>
    disconnect: () => Promise<void>
    setDispatch: (dispatch: ((action: ClientAction) => void) | null) => void
    setActionHandler: (handler: ((action: ClientAction) => boolean) | null) => void
    updatePlayerConfig: (config: PlayerConfig) => Promise<void>
    setPlayerReady: (ready: boolean) => Promise<void>
    getConnectedPlayers: () => LobbyPlayer[]
    clearError: () => void
    clearHostDisconnected: () => void
    clearWasKicked: () => void
    clearClientDisconnected: () => void
}

// Context
const MultiplayerContext = createContext<MultiplayerContextValue | null>(null)

// Generate a persistent player ID for this browser session
const getOrCreatePlayerId = (): string => {
    let playerId = sessionStorage.getItem('helldrafters_player_id')
    if (!playerId) {
        playerId = uuidv4()
        sessionStorage.setItem('helldrafters_player_id', playerId)
    }
    return playerId
}

// =============================================================================
// PROVIDER COMPONENT
// =============================================================================

interface MultiplayerProviderProps {
    children: ReactNode
}

/**
 * Multiplayer Provider Component
 */
export function MultiplayerProvider({ children }: MultiplayerProviderProps) {
    // Multiplayer state
    const [isMultiplayer, setIsMultiplayer] = useState(false)
    const [isHost, setIsHost] = useState(false)
    const [lobbyId, setLobbyId] = useState<string | null>(null)
    const [lobbyData, setLobbyData] = useState<LobbyData | null>(null)
    const [playerId, setPlayerId] = useState(getOrCreatePlayerId)
    const [playerSlot, setPlayerSlot] = useState<number | null>(null)
    const [playerName, setPlayerName] = useState('')
    const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>('disconnected')
    const [error, setError] = useState<string | null>(null)
    const [firebaseReady, setFirebaseReady] = useState(false)
    const [hostDisconnected, setHostDisconnected] = useState(false) // Track if host closed the lobby
    const [wasKicked, setWasKicked] = useState(false) // Track if player was kicked
    const [clientDisconnected, setClientDisconnected] = useState(false) // Track if client intentionally disconnected

    // Dispatch ref - set by the game component
    const dispatchRef = useRef<((action: ClientAction) => void) | null>(null)

    // Handler for special actions (like DRAFT_PICK) that need app-level processing
    const actionHandlerRef = useRef<((action: ClientAction) => boolean) | null>(null)

    // Ref for lobbyData to avoid stale closures in subscriptions
    const lobbyDataRef = useRef<LobbyData | null>(null)

    // Refs for cleanup
    const lobbyUnsubscribeRef = useRef<Unsubscribe | null>(null)
    const stateUnsubscribeRef = useRef<Unsubscribe | null>(null)
    const actionsUnsubscribeRef = useRef<Unsubscribe | null>(null)
    const disconnectRef = useRef<(() => Promise<void>) | null>(null)

    // Initialize Firebase on mount
    useEffect(() => {
        const init = async () => {
            if (isFirebaseConfigured()) {
                const success = await initializeFirebase()
                setFirebaseReady(success)
            }
        }
        init()
    }, [])

    // Keep lobbyDataRef in sync with lobbyData state
    useEffect(() => {
        lobbyDataRef.current = lobbyData
    }, [lobbyData])

    // Cleanup on unmount
    useEffect(
        () => () => {
            if (lobbyUnsubscribeRef.current) lobbyUnsubscribeRef.current()
            if (stateUnsubscribeRef.current) stateUnsubscribeRef.current()
            if (actionsUnsubscribeRef.current) actionsUnsubscribeRef.current()
        },
        [],
    )

    /**
     * Host: Create a new lobby
     */
    const hostGame = useCallback(
        async (hostName: string, gameConfig: GameConfig): Promise<string | null> => {
            if (!firebaseReady) {
                setError('Firebase not configured')
                return null
            }

            setConnectionStatus('connecting')
            setError(null)

            try {
                const newLobbyId = generateLobbyId()
                const hostInfo = { id: playerId, name: hostName }

                await createLobby(newLobbyId, hostInfo, gameConfig)

                setLobbyId(newLobbyId)
                setIsHost(true)
                setIsMultiplayer(true)
                setPlayerSlot(0)
                setPlayerName(hostName)
                setConnectionStatus('connected')

                // Subscribe to lobby updates
                lobbyUnsubscribeRef.current = subscribeLobby(newLobbyId, (lobby) => {
                    if (lobby) {
                        setLobbyData(lobby)
                    } else {
                        // Lobby was deleted
                        setError('Lobby was closed')
                        if (disconnectRef.current) disconnectRef.current()
                    }
                })

                return newLobbyId
            } catch (err) {
                console.error('Failed to host game:', err)
                setError((err as Error).message)
                setConnectionStatus('disconnected')
                return null
            }
        },
        [firebaseReady, playerId],
    )

    /**
     * Client: Join an existing lobby
     */
    const joinGame = useCallback(
        async (joinLobbyId: string, name: string, slot: number): Promise<boolean> => {
            if (!firebaseReady) {
                setError('Firebase not configured')
                return false
            }

            setConnectionStatus('connecting')
            setError(null)

            try {
                let activePlayerId = playerId
                let didRetry = false
                let result = await joinLobby(joinLobbyId, { id: activePlayerId, name }, slot)

                if (!result.success && result.errorCode === 'PLAYER_ID_CONFLICT') {
                    didRetry = true
                    activePlayerId = uuidv4()
                    sessionStorage.setItem('helldrafters_player_id', activePlayerId)
                    setPlayerId(activePlayerId)
                    result = await joinLobby(joinLobbyId, { id: activePlayerId, name }, slot)
                }

                if (!result.success) {
                    if (didRetry && result.errorCode === 'PLAYER_ID_CONFLICT') {
                        setError('Unable to join lobby. Please try again.')
                    } else {
                        setError(result.error || 'Failed to join lobby')
                    }
                    setConnectionStatus('disconnected')
                    return false
                }

                setLobbyId(joinLobbyId)
                setIsHost(false)
                setIsMultiplayer(true)
                setPlayerSlot(slot)
                setPlayerName(name)
                setConnectionStatus('connected')

                // Subscribe to lobby updates
                lobbyUnsubscribeRef.current = subscribeLobby(joinLobbyId, (lobby) => {
                    if (lobby) {
                        // Check if current player has been kicked (no longer in players list)
                        const stillInLobby =
                            lobby.players && Object.keys(lobby.players).includes(playerId)
                        if (!stillInLobby) {
                            // Player was kicked - cleanup subscriptions but don't set clientDisconnected
                            // (so the kicked screen shows instead of going straight to menu)
                            if (lobbyUnsubscribeRef.current) {
                                lobbyUnsubscribeRef.current()
                                lobbyUnsubscribeRef.current = null
                            }
                            if (stateUnsubscribeRef.current) {
                                stateUnsubscribeRef.current()
                                stateUnsubscribeRef.current = null
                            }
                            if (actionsUnsubscribeRef.current) {
                                actionsUnsubscribeRef.current()
                                actionsUnsubscribeRef.current = null
                            }
                            // Reset multiplayer state
                            setIsMultiplayer(false)
                            setIsHost(false)
                            setLobbyId(null)
                            setLobbyData(null)
                            setPlayerSlot(null)
                            setConnectionStatus('disconnected')
                            setError(null)
                            // Set kicked flag LAST so the kicked screen appears
                            setWasKicked(true)
                        } else {
                            setLobbyData(lobby)
                        }
                    } else {
                        // Lobby was deleted/closed by host
                        setError('Lobby was closed by host')
                        setHostDisconnected(true) // Signal that host disconnected
                        if (disconnectRef.current) disconnectRef.current()
                    }
                })

                // Subscribe to game state updates (clients only)
                stateUnsubscribeRef.current = subscribeGameState(joinLobbyId, (state) => {
                    if (state && dispatchRef.current) {
                        // Update local state with synced state from host
                        dispatchRef.current({
                            type: 'LOAD_GAME_STATE',
                            payload: state as Record<string, unknown>,
                        })
                    }
                })

                return true
            } catch (err) {
                console.error('Failed to join game:', err)
                setError((err as Error).message)
                setConnectionStatus('disconnected')
                return false
            }
        },
        [firebaseReady, playerId],
    )

    /**
     * Check if a lobby exists and get its info
     */
    const checkLobbyExists = useCallback(
        async (checkId: string): Promise<LobbyInfo | null> => {
            if (!firebaseReady) return null
            return await checkLobby(checkId)
        },
        [firebaseReady],
    )

    /**
     * Get available slots for a lobby
     */
    const getSlots = useCallback((): number[] => {
        if (!lobbyData) return []
        return getAvailableSlots(lobbyData)
    }, [lobbyData])

    /**
     * Change player's slot (pre-game only)
     */
    const changeSlot = useCallback(
        async (newSlot: number): Promise<boolean> => {
            if (!lobbyId || !playerId) return false

            const result = await changePlayerSlot(lobbyId, playerId, newSlot)
            if (result.success) {
                setPlayerSlot(newSlot)
            } else {
                setError(result.error || 'Failed to change slot')
            }
            return result.success
        },
        [lobbyId, playerId],
    )

    /**
     * Host: Kick a player from the lobby (frees their slot for rejoining)
     */
    const kickPlayerFromLobby = useCallback(
        async (playerIdToKick: string): Promise<boolean> => {
            if (!isHost || !lobbyId) return false

            const result = await kickPlayer(lobbyId, playerIdToKick)
            if (!result.success) {
                setError(result.error || 'Failed to kick player')
            }
            return result.success
        },
        [isHost, lobbyId],
    )

    /**
     * Host: Start the game
     */
    const startMultiplayerGame = useCallback(
        async (loadLobbyId?: string, forceHost?: boolean): Promise<void> => {
            const activeLobbyId = loadLobbyId || lobbyId
            const activeIsHost = forceHost !== undefined ? forceHost : isHost
            if (!activeIsHost || !activeLobbyId) return

            // eslint-disable-next-line no-console
            console.log('Starting multiplayer game, lobbyId:', activeLobbyId)
            await updateLobbyStatus(activeLobbyId, 'in-game')

            // Start listening for client actions
            actionsUnsubscribeRef.current = subscribeClientActions(
                activeLobbyId,
                async (actionData: ActionData, actionId: string) => {
                    console.debug('Received client action:', actionData)
                    // Process the action
                    const { playerId: actionPlayerId, action } = actionData

                    // Use ref to get current lobby data (avoids stale closure)
                    const currentLobbyData = lobbyDataRef.current

                    // Find the player's slot
                    const player = Object.values(currentLobbyData?.players || {}).find(
                        (p) => p.id === actionPlayerId,
                    )
                    if (!player) {
                        console.warn('Action from unknown player:', actionPlayerId)
                        await removeClientAction(activeLobbyId, actionId)
                        return
                    }

                    // Validate action is allowed for this player
                    if (!isActionAllowedForClient(action, player.slot)) {
                        console.warn('Unauthorized action from player:', action.type)
                        await removeClientAction(activeLobbyId, actionId)
                        return
                    }

                    // Check if there's a special handler for this action type
                    if (actionHandlerRef.current && actionHandlerRef.current(action)) {
                        // Handler processed the action
                        await removeClientAction(activeLobbyId, actionId)
                        return
                    }

                    // Dispatch the action locally (host processes it)
                    if (dispatchRef.current) {
                        dispatchRef.current(action)
                    }

                    // Remove processed action
                    await removeClientAction(activeLobbyId, actionId)
                },
            )
        },
        [isHost, lobbyId],
    )

    /**
     * Host: Sync current state to clients
     */
    const syncState = useCallback(
        async (state: unknown): Promise<void> => {
            if (!isHost || !lobbyId) return

            try {
                await syncGameState(lobbyId, state)
            } catch (err) {
                console.error('Failed to sync state:', err)
            }
        },
        [isHost, lobbyId],
    )

    /**
     * Client: Send an action to the host
     */
    const sendAction = useCallback(
        async (action: ClientAction): Promise<void> => {
            if (isHost || !lobbyId || !playerId) return

            // Validate action locally first
            if (playerSlot === null || !isActionAllowedForClient(action, playerSlot)) {
                console.warn('Action not allowed:', action.type)
                return
            }

            try {
                await sendClientAction(lobbyId, playerId, action)
            } catch (err) {
                console.error('Failed to send action:', err)
                setError('Failed to send action')
            }
        },
        [isHost, lobbyId, playerId, playerSlot],
    )

    /**
     * Disconnect from multiplayer (intentional disconnect by user)
     */
    const disconnect = useCallback(async (): Promise<void> => {
        // Cleanup subscriptions
        if (lobbyUnsubscribeRef.current) {
            lobbyUnsubscribeRef.current()
            lobbyUnsubscribeRef.current = null
        }
        if (stateUnsubscribeRef.current) {
            stateUnsubscribeRef.current()
            stateUnsubscribeRef.current = null
        }
        if (actionsUnsubscribeRef.current) {
            actionsUnsubscribeRef.current()
            actionsUnsubscribeRef.current = null
        }

        // Leave/close lobby
        if (lobbyId && playerId) {
            if (isHost) {
                await closeLobby(lobbyId)
                // Host also needs to be returned to menu
                setClientDisconnected(true)
            } else {
                await leaveLobby(lobbyId, playerId)
                // Set flag that client intentionally disconnected (to trigger menu return)
                setClientDisconnected(true)
            }
        }

        // Reset state
        setIsMultiplayer(false)
        setIsHost(false)
        setLobbyId(null)
        setLobbyData(null)
        setPlayerSlot(null)
        setConnectionStatus('disconnected')
        setError(null)
    }, [lobbyId, playerId, isHost])

    // Keep disconnect ref up to date
    useEffect(() => {
        disconnectRef.current = disconnect
    }, [disconnect])

    /**
     * Update player's configuration (name, warbonds, ready state)
     */
    const updatePlayerConfig = useCallback(
        async (config: PlayerConfig): Promise<void> => {
            if (!lobbyId || !playerId) return

            try {
                await updatePlayerConfigInLobby(lobbyId, playerId, config)

                // Update local player name if changed
                if (config.name !== undefined) {
                    setPlayerName(config.name)
                }
            } catch (err) {
                console.error('Failed to update player config:', err)
                setError('Failed to update configuration')
            }
        },
        [lobbyId, playerId],
    )

    /**
     * Set player's ready state
     */
    const setPlayerReady = useCallback(
        async (ready: boolean): Promise<void> => {
            if (!lobbyId || !playerId) return

            try {
                await setPlayerReadyInLobby(lobbyId, playerId, ready)
            } catch (err) {
                console.error('Failed to set ready state:', err)
                setError('Failed to update ready state')
            }
        },
        [lobbyId, playerId],
    )

    /**
     * Get list of connected players from lobby data
     */
    const getConnectedPlayers = useCallback((): LobbyPlayer[] => {
        if (!lobbyData?.players) return []
        return Object.values(lobbyData.players)
            .filter((p) => p.connected)
            .sort((a, b) => a.slot - b.slot)
    }, [lobbyData])

    /**
     * Register dispatch function from game component
     */
    const setDispatch = useCallback((dispatch: ((action: ClientAction) => void) | null): void => {
        dispatchRef.current = dispatch
    }, [])

    /**
     * Register action handler for special actions (like DRAFT_PICK)
     * Handler should return true if it processed the action
     */
    const setActionHandler = useCallback(
        (handler: ((action: ClientAction) => boolean) | null): void => {
            actionHandlerRef.current = handler
        },
        [],
    )

    // Context value
    const value: MultiplayerContextValue = {
        // State
        isMultiplayer,
        isHost,
        lobbyId,
        lobbyData,
        playerId,
        playerSlot,
        playerName,
        connectionStatus,
        error,
        firebaseReady,
        hostDisconnected,
        wasKicked,
        clientDisconnected,

        // Computed
        connectedPlayers: lobbyData?.players ? Object.values(lobbyData.players) : [],

        // Actions
        hostGame,
        joinGame,
        checkLobbyExists,
        getSlots,
        changeSlot,
        kickPlayerFromLobby,
        startMultiplayerGame,
        syncState,
        sendAction,
        disconnect,
        setDispatch,
        setActionHandler,
        updatePlayerConfig,
        setPlayerReady,
        getConnectedPlayers,
        clearError: () => setError(null),
        clearHostDisconnected: () => setHostDisconnected(false),
        clearWasKicked: () => setWasKicked(false),
        clearClientDisconnected: () => setClientDisconnected(false),
    }

    return <MultiplayerContext.Provider value={value}>{children}</MultiplayerContext.Provider>
}

// =============================================================================
// HOOKS
// =============================================================================

/**
 * Hook to use multiplayer context
 */
export function useMultiplayer(): MultiplayerContextValue {
    const context = useContext(MultiplayerContext)
    if (!context) {
        throw new Error('useMultiplayer must be used within a MultiplayerProvider')
    }
    return context
}
